created=[]

def components(*marks):
 return [(f'component-{i}',f'Component {i}',m) for i,m in enumerate(marks,1)]
def rs(label,marks,labels=None):
 return response(1,label,[(f'component-{i}',labels[i-1] if labels else f'Component {i}',m) for i,m in enumerate(marks,1)])
def rows(labels,marks=(2,3)):
 return [response(i,label,[('explain','Explanation',marks[0]),('develop','Development',marks[1])]) for i,label in enumerate(labels,1)]
def add(section,q,suffix,prompt,total,topic,concept,page,support,requirement,responses,guidance=None,extra=None,marknote=None):
 part=''.join(f'({v.upper() if section==3 and i==0 else v})' for i,v in enumerate(suffix.split('-'))) if suffix else ''
 tariff=5 if section==1 else 7 if q<=2 else 8 if q==3 else 9 if q<=5 else 10
 c=dict(id=f'bus-2014-hl-s{section}-q{q}{suffix}',year=year,level='higher',section=str(section),paperFileid='LC033ALP000EV',paperPages=[page],sourceLabel='QUESTION PAPER',sourceTitle=f'2014 Business · Section {section} Question {q}',questionRef=f'2014 HL Section {section} Q{q}{part}',questionText=prompt,totalMarks=total,topicId=topic,conceptId=concept,rubric=dict(system='business',taskRequirements=[requirement],guidance=guidance or [],responses=responses,schemeFileid='LC033ALP000EV',schemePages=[tariff]+support,markingGuideNote=marknote or notes))
 if extra:c['additionalTopicIds']=extra
 assert sum(a['maxMarks'] for r in responses for a in r['allocations'])==total,c['id']
 created.append(c)
 return c

